//! The 48 lvim themes, as GPUI colours.
//!
//! **The files are not touched by this port.** They are the editor's own
//! resolved highlight groups, generated by lvim-colorscheme, and they were the
//! point of a long argument: `text.primary` is `Normal.fg`, at whatever contrast
//! the editor has it (`#5e8888` on base dark, 3.86:1), because a client that
//! sits beside the editor all day has to be the same colour as the editor.
//! Only the code that READS them moved from egui to GPUI; every value is the
//! same byte it was.
//!
//! Corners stay square — there is no radius anywhere in this client.

use std::collections::BTreeMap;
use std::path::PathBuf;

use gpui::{rgb, Rgba};
use serde::Deserialize;

#[allow(dead_code)] // the file is the contract; see the note in the generator
#[derive(Debug, Clone, Deserialize)]
pub struct Theme {
    pub name: String,
    #[serde(default)]
    pub style: String,
    #[serde(default)]
    pub dark: bool,
    pub surface: Surface,
    pub text: Text,
    pub accent: Accent,
    #[serde(default)]
    pub syntax: Syntax,
    #[serde(default, rename = "match")]
    pub match_: Match,
    pub grid: Grid,
    #[serde(default)]
    pub palette: BTreeMap<String, String>,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Surface {
    /// `Normal.bg` — the buffer: the grid and the editor.
    pub base: String,
    /// `NormalSB.bg` — the editor's own side panel.
    pub panel: String,
    /// `Pmenu.bg` — a popup list's body, the nearest thing to a card.
    pub raised: String,
    /// `NormalFloat.bg` — a float: dialogs.
    pub overlay: String,
    /// `StatusLine.bg`.
    #[serde(default)]
    pub status: String,
    /// `CursorLine.bg` — the row under the pointer.
    #[serde(default)]
    pub hover: String,
    /// `PmenuSel.bg` — a selected entry in a LIST (not selected text).
    #[serde(default)]
    pub selected: String,
    /// `WinSeparator.fg`, which on every lvim style equals its own background:
    /// the editor draws no line between windows, and neither does this.
    pub border: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Text {
    pub primary: String,
    /// `Comment`, deliberately not `LineNr`.
    pub muted: String,
    #[serde(default)]
    pub title: String,
    pub inverted: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Accent {
    pub primary: String,
    pub secondary: String,
    pub success: String,
    pub warning: String,
    pub error: String,
    pub info: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Default, Deserialize)]
pub struct Syntax {
    #[serde(default)]
    pub keyword: String,
    #[serde(default)]
    pub string: String,
    #[serde(default)]
    pub number: String,
    #[serde(default)]
    pub comment: String,
    #[serde(default)]
    pub function: String,
    #[serde(default)]
    pub operator: String,
    #[serde(default)]
    pub identifier: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Default, Deserialize)]
pub struct Match {
    #[serde(default)]
    pub bg: String,
    #[serde(default)]
    pub fg: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Grid {
    pub header_bg: String,
    pub header_fg: String,
    pub row_alt: String,
    pub selection_bg: String,
    pub selection_fg: String,
    pub null_fg: String,
    /// `LineNr` — the row-number column and nothing else.
    #[serde(default)]
    pub line_nr: String,
}

/// Parse `#rrggbb`, or `None` when it is not one.
pub fn parse_hex(s: &str) -> Option<Rgba> {
    let t = s.trim().trim_start_matches('#');
    if t.len() != 6 {
        return None;
    }
    u32::from_str_radix(t, 16).ok().map(rgb)
}

/// Parse `#rrggbb`. One unreadable value costs one colour, never the theme.
pub fn hex(s: &str, fallback: Rgba) -> Rgba {
    parse_hex(s).unwrap_or(fallback)
}

/// The two roots of the fallback chain, read from the BUILT-IN theme rather
/// than written as literals here.
///
/// Every other role falls back to another role; these two had nowhere left to
/// fall, and were a hard-coded `#20272b` and `#ffffff` in the working code.
/// A number in the source is a colour that did not come from the theme, which
/// is the one rule this client has about colour. The built-in theme is the
/// generated `LvimBase_dark` byte for byte, so it is guaranteed complete and
/// valid — meaning a default has somewhere to come from without a literal.
///
/// Resolved once: `builtin()` parses a TOML document, and doing that per call
/// of `base()` would parse it thousands of times a frame.
/// Both `expect` rather than falling back again, and that is the point: there
/// is no fourth place for a colour to come from, so inventing one would mean
/// writing the literal this removed. The built-in theme is checked in, parsed by
/// `builtin()` (which already panics on a malformed document) and asserted
/// against the editor's own groups by a test — a build in which these fail is a
/// build whose theme file is broken, and that should stop, not dim.
fn root_bg() -> Rgba {
    static ROOT: std::sync::OnceLock<Rgba> = std::sync::OnceLock::new();
    *ROOT.get_or_init(|| {
        parse_hex(&Theme::builtin().surface.base).expect("the built-in theme's surface.base must be #rrggbb")
    })
}

fn root_fg() -> Rgba {
    static ROOT: std::sync::OnceLock<Rgba> = std::sync::OnceLock::new();
    *ROOT.get_or_init(|| {
        parse_hex(&Theme::builtin().text.primary).expect("the built-in theme's text.primary must be #rrggbb")
    })
}

impl Theme {
    // Each role falls back to a surface that is certainly there, so a theme
    // missing one is dimmer, never broken. Written out rather than generated:
    // the fallback CHAIN is the interesting part and a macro hides it.
    pub fn base(&self) -> Rgba {
        hex(&self.surface.base, root_bg())
    }
    pub fn panel(&self) -> Rgba {
        hex(&self.surface.panel, self.base())
    }
    pub fn raised(&self) -> Rgba {
        hex(&self.surface.raised, self.base())
    }
    pub fn overlay(&self) -> Rgba {
        hex(&self.surface.overlay, self.panel())
    }
    pub fn status(&self) -> Rgba {
        hex(&self.surface.status, self.panel())
    }
    pub fn hover(&self) -> Rgba {
        hex(&self.surface.hover, self.raised())
    }
    pub fn selected(&self) -> Rgba {
        hex(&self.surface.selected, self.hover())
    }
    pub fn border(&self) -> Rgba {
        hex(&self.surface.border, self.raised())
    }
    pub fn fg(&self) -> Rgba {
        hex(&self.text.primary, root_fg())
    }
    pub fn muted(&self) -> Rgba {
        hex(&self.text.muted, self.fg())
    }
    pub fn title(&self) -> Rgba {
        hex(&self.text.title, self.muted())
    }
    pub fn inverted(&self) -> Rgba {
        hex(&self.text.inverted, self.base())
    }
    pub fn accent(&self) -> Rgba {
        hex(&self.accent.primary, self.fg())
    }
    pub fn success(&self) -> Rgba {
        hex(&self.accent.success, self.accent())
    }
    pub fn warning(&self) -> Rgba {
        hex(&self.accent.warning, self.accent())
    }
    pub fn error(&self) -> Rgba {
        hex(&self.accent.error, self.accent())
    }
    pub fn header_bg(&self) -> Rgba {
        hex(&self.grid.header_bg, self.raised())
    }
    pub fn header_fg(&self) -> Rgba {
        hex(&self.grid.header_fg, self.fg())
    }
    pub fn row_alt(&self) -> Rgba {
        hex(&self.grid.row_alt, self.base())
    }
    pub fn selection_bg(&self) -> Rgba {
        hex(&self.grid.selection_bg, self.selected())
    }
    pub fn selection_fg(&self) -> Rgba {
        hex(&self.grid.selection_fg, self.fg())
    }
    pub fn null_fg(&self) -> Rgba {
        hex(&self.grid.null_fg, self.muted())
    }
    pub fn line_nr(&self) -> Rgba {
        hex(&self.grid.line_nr, self.muted())
    }

    // ── DERIVED roles ───────────────────────────────────────────────────────
    //
    // **Nothing below changes an editor pair.** The rule at the top of this
    // file — every value is the same byte the editor has — is about the roles
    // the EDITOR defines, and it still holds: not one of them is touched here.
    //
    // These are roles the editor does not have. An editor has no "the row you
    // are on in a result grid, which must be visible against the panel it sits
    // on" and no "this control is off". Where a theme's own surface is too
    // close to its neighbour for the job — `selected` sits one step from
    // `hover` on nearly every light palette, and both are a hair from `panel`
    // — the colour is MIXED from two of the theme's own values rather than
    // chosen. A mix is still the theme: it has no colour of its own in it.
    //
    // If you are here to delete this "because of the rule": the rule is about
    // the editor's pairs. Deleting it brings back a selected row that cannot be
    // seen on 24 of the 48 palettes.

    /// How visible `a` is against `b`, as a WCAG contrast ratio.
    pub fn contrast(a: Rgba, b: Rgba) -> f32 {
        let lum = |c: Rgba| {
            let f = |v: f32| if v <= 0.03928 { v / 12.92 } else { ((v + 0.055) / 1.055).powf(2.4) };
            0.2126 * f(c.r) + 0.7152 * f(c.g) + 0.0722 * f(c.b)
        };
        let (x, y) = (lum(a), lum(b));
        let (hi, lo) = if x > y { (x, y) } else { (y, x) };
        (hi + 0.05) / (lo + 0.05)
    }

    /// `a` laid over `b` at `alpha`. Linear, on the stored components, so the
    /// result is between two of the theme's own colours and nothing else.
    pub fn mix(a: Rgba, b: Rgba, alpha: f32) -> Rgba {
        let k = alpha.clamp(0.0, 1.0);
        Rgba {
            r: b.r + (a.r - b.r) * k,
            g: b.g + (a.g - b.g) * k,
            b: b.b + (a.b - b.b) * k,
            a: 1.0,
        }
    }

    /// The weakest mix of `over` onto `under` that reaches `want`.
    ///
    /// A fixed ladder rather than arithmetic, because contrast is not linear in
    /// alpha: it depends on both colours' luminance, so "how much accent do I
    /// need here" has a different answer on every one of the 48 palettes. The
    /// ladder climbs until the answer is yes and stops, which keeps the mark as
    /// close to the theme's own surface as the job allows.
    ///
    /// `second` is tried when `over` cannot get there at any strength — an
    /// accent whose luminance is near the panel's is invisible on it however
    /// much is used, and on those palettes the ordinary foreground is what is
    /// left. Both are the theme's own colours either way.
    fn toward(over: Rgba, second: Rgba, under: Rgba, want: f32) -> Rgba {
        for c in [over, second] {
            for k in [0.08, 0.12, 0.18, 0.25, 0.34, 0.45, 0.6] {
                let m = Self::mix(c, under, k);
                if Self::contrast(m, under) >= want {
                    return m;
                }
            }
        }
        // Nothing reached it. The strongest mix is still the best answer there
        // is, and it is better than silently returning the surface itself.
        Self::mix(second, under, 0.6)
    }

    /// The background under the pointer.
    ///
    /// The theme's own `hover` when it can be told apart from the panel at all;
    /// otherwise the faintest mix that can. A hover is the weaker of the two
    /// marks by construction — see `selected_mark`.
    pub fn hover_mark(&self) -> Rgba {
        let own = self.hover();
        if Self::contrast(own, self.panel()) >= 1.18 {
            own
        } else {
            Self::toward(self.accent(), self.fg(), self.panel(), 1.2)
        }
    }

    /// The background of the row, tab or list entry that is CHOSEN.
    ///
    /// The theme's own `selected` when it is BOTH visible against the panel and
    /// louder than the hover; otherwise a mix that is. On most light palettes
    /// `surface.selected` is within a percent of `surface.panel` — so "which
    /// row am I on" had no answer — and on several it is quieter than
    /// `surface.hover`, which means the row under the pointer looked more
    /// chosen than the chosen one.
    pub fn selected_mark(&self) -> Rgba {
        let floor = 1.45_f32.max(Self::contrast(self.hover_mark(), self.panel()) * 1.15);
        let own = self.selected();
        if Self::contrast(own, self.panel()) >= floor {
            own
        } else {
            Self::toward(self.accent(), self.fg(), self.panel(), floor)
        }
    }

    /// The ink for something that is there but cannot be used.
    ///
    /// `border` was being used for this — a BORDER colour as TEXT, which is
    /// below 2:1 on most palettes and reads as a rendering fault rather than
    /// as "not available". Dimmer than the real text, still legible: it has to
    /// be READ to know what is unavailable.
    pub fn disabled(&self) -> Rgba {
        Self::toward(self.muted(), self.fg(), self.panel(), 2.2)
    }

    /// The ink for a row number or a line number.
    ///
    /// `line_nr` is the editor's GUTTER colour, meant to be nearly invisible
    /// beside code. In a result grid the row number is something people count
    /// along, so it gets the ordinary muted ink and `line_nr` stays for the
    /// gutter's own background.
    pub fn row_number(&self) -> Rgba {
        self.muted()
    }

    /// A line that has to be SEEN: a tile's edge, a panel's grip, a column's
    /// handle. `border` disappears into the base on half the palettes, which
    /// is right for a box's edge and wrong for a divider somebody has to aim
    /// at with a pointer.
    pub fn divider(&self) -> Rgba {
        Self::toward(self.muted(), self.fg(), self.base(), 2.0)
    }

    /// The colour one run of a statement is drawn in — see `editor::sql_runs`.
    ///
    /// The seven roles are the seven the 48 themes carry: the generator reads
    /// the editor's own `syntax.*` groups, so a statement in this window is
    /// coloured exactly as the same statement is in the editor.
    pub fn sql_role(&self, role: crate::editor::SqlRole) -> Rgba {
        use crate::editor::SqlRole as R;
        match role {
            R::Keyword => hex(&self.syntax.keyword, self.accent()),
            R::Str => hex(&self.syntax.string, self.fg()),
            R::Num => hex(&self.syntax.number, self.fg()),
            R::Comment => hex(&self.syntax.comment, self.muted()),
            R::Ident => hex(&self.syntax.identifier, self.fg()),
            R::Operator => hex(&self.syntax.operator, self.muted()),
            R::Plain => self.fg(),
        }
    }

    /// The colour one run of JSON is drawn in — see `workspace::json_runs`.
    ///
    /// The editor's own syntax colours, which already name these four things:
    /// the JSON view used one ink for everything, so a document of forty fields
    /// was forty lines the same colour and finding a value meant reading it.
    pub fn json_role(&self, role: crate::workspace::JsonRole) -> Rgba {
        use crate::workspace::JsonRole as R;
        match role {
            R::Key => hex(&self.syntax.identifier, self.fg()),
            R::Str => hex(&self.syntax.string, self.fg()),
            R::Num => hex(&self.syntax.number, self.fg()),
            R::Word => hex(&self.syntax.keyword, self.accent()),
            // The braces and the commas are the SHAPE, not the content: quiet,
            // so the indentation reads as structure rather than as text.
            R::Punct => self.disabled(),
        }
    }

    /// The colour a type badge is drawn in. Mapped from the badge word rather
    /// than from a driver name, so a type this client has never heard of lands
    /// on the neutral ink instead of nothing.
    /// The colour of the nth thing in a chart.
    ///
    /// Themes have no palette for series, so the roles are used in an order
    /// that keeps neighbours apart: accent, success, warning, error, then two
    /// mixes of accent towards the foreground and the panel. Six is enough for
    /// a pie of six slices, and past that they repeat — a chart of twelve
    /// categories is unreadable whatever the colours, and the honest fix is
    /// fewer categories, not more hues nobody can tell apart.
    ///
    /// They are ROLES rather than fixed hues so a chart in a light theme and a
    /// chart in a dark one are both legible: a palette picked for one would be
    /// invisible in the other.
    pub fn series(&self, n: usize) -> Rgba {
        let all = self.series_all();
        all[n % all.len()]
    }

    /// The six, built so that no two of them are the same colour.
    ///
    /// Picking four roles and two mixes was not enough: in `LvimBase_darker`
    /// the accent and the success colour are within a hundredth of each other,
    /// and two adjacent slices of a pie in one colour is one slice. So a
    /// candidate too close to one already taken is SKIPPED, and the list is
    /// filled out with mixes of what was taken against the foreground and the
    /// panel — which are the two directions guaranteed to move a colour away
    /// from the others while staying visible on this theme's background.
    fn series_all(&self) -> Vec<Rgba> {
        // A rough "same colour to the eye" test. Not contrast: two colours can
        // have equal luminance and be plainly different (blue and red), and
        // contrast would call those a clash.
        let near = |a: Rgba, b: Rgba| {
            (a.r - b.r).abs() + (a.g - b.g).abs() + (a.b - b.b).abs() < 0.12
        };
        let mut out: Vec<Rgba> = Vec::with_capacity(6);
        let candidates = [
            self.accent(),
            self.success(),
            self.warning(),
            self.error(),
            Self::mix(self.fg(), self.accent(), 0.5),
            Self::mix(self.accent(), self.panel(), 0.4),
            Self::mix(self.warning(), self.fg(), 0.35),
            Self::mix(self.error(), self.panel(), 0.35),
            Self::mix(self.success(), self.fg(), 0.4),
            self.title(),
            self.fg(),
            self.muted(),
        ];
        for c in candidates {
            if out.len() == 6 {
                break;
            }
            // Invisible against the canvas is not a colour either.
            if Self::contrast(c, self.base()) < 1.3 {
                continue;
            }
            if out.iter().any(|&o| near(o, c)) {
                continue;
            }
            out.push(c);
        }
        // A theme so flat that twelve candidates gave fewer than two: the
        // foreground, which every theme has to be able to show.
        if out.is_empty() {
            out.push(self.fg());
        }
        out
    }

    pub fn badge(&self, kind: &str) -> Rgba {
        match kind {
            "string" => hex(&self.syntax.string, self.fg()),
            "int" | "num" => hex(&self.syntax.number, self.fg()),
            "bool" => hex(&self.syntax.keyword, self.fg()),
            "null" => self.null_fg(),
            "object" | "array" => hex(&self.syntax.function, self.accent()),
            "oid" => hex(&self.syntax.identifier, self.accent()),
            "date" => hex(&self.syntax.keyword, self.accent()),
            _ => self.muted(),
        }
    }

    /// The built-in theme: byte for byte the generated LvimBase_dark, so the
    /// window looks the same before a theme is installed and after.
    pub fn builtin() -> Theme {
        toml::from_str(include_str!("builtin_theme.toml")).expect("the built-in theme must parse")
    }
}

/// Where themes are looked for, in order.
pub fn theme_dirs() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Some(d) = std::env::var_os("LODE_THEME_DIR") {
        out.push(PathBuf::from(d));
    }
    if let Some(d) = std::env::var_os("XDG_CONFIG_HOME") {
        out.push(PathBuf::from(d).join("lode/themes"));
    }
    if let Some(h) = std::env::var_os("HOME") {
        out.push(PathBuf::from(h).join(".config/lode/themes"));
    }
    out
}

/// Every theme file found, by name. The first directory wins a clash.
pub fn discover() -> BTreeMap<String, PathBuf> {
    let mut found: BTreeMap<String, PathBuf> = BTreeMap::new();
    for dir in theme_dirs() {
        let Ok(entries) = std::fs::read_dir(&dir) else { continue };
        for e in entries.flatten() {
            let p = e.path();
            if p.extension().and_then(|s| s.to_str()) != Some("toml") {
                continue;
            }
            let Some(stem) = p.file_stem().and_then(|s| s.to_str()) else { continue };
            found.entry(stem.to_string()).or_insert(p);
        }
    }
    found
}

pub fn load(path: &std::path::Path) -> anyhow::Result<Theme> {
    let text = std::fs::read_to_string(path)?;
    toml::from_str(&text).map_err(|e| anyhow::anyhow!("{}: {e}", path.display()))
}

/// The theme to start with: `$LODE_THEME`, else the first found, else built in.
pub fn pick() -> (String, Theme) {
    pick_named(None)
}

/// The theme to start with, preferring one by name.
///
/// `want` is what the session remembered. It comes FIRST because it is the most
/// recent thing the person actually chose; `$LODE_THEME` is next because it is
/// deliberate too but set once; and the first file found is a fallback rather
/// than a choice. The session's theme was being saved and never read — a picker
/// that forgets is a picker that has to be used every morning.
pub fn pick_named(want: Option<&str>) -> (String, Theme) {
    let themes = discover();
    for name in want.map(str::to_string).into_iter().chain(std::env::var("LODE_THEME").ok()) {
        if let Some(p) = themes.get(&name) {
            if let Ok(t) = load(p) {
                return (name, t);
            }
        }
    }
    for (name, path) in &themes {
        if let Ok(t) = load(path) {
            return (name.clone(), t);
        }
    }
    let t = Theme::builtin();
    (t.name.clone(), t)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hex_parses_and_falls_back() {
        assert_eq!(hex("#20272b", rgb(0xff0000)).r, rgb(0x20272b).r);
        assert_eq!(hex("20272b", rgb(0xff0000)).g, rgb(0x20272b).g);
        assert_eq!(hex("nope", rgb(0xff0000)).r, rgb(0xff0000).r);
        assert_eq!(hex("#12345", rgb(0xff0000)).r, rgb(0xff0000).r);
    }

    /// Six series, all visible against the background, and no two the same.
    ///
    /// On every theme installed: a palette that works on the dark one and
    /// disappears on the light one is a chart that is blank for whoever picked
    /// the light one.
    #[test]
    fn every_series_can_be_seen_and_told_apart() {
        let mut themes = vec![("builtin".to_string(), Theme::builtin())];
        for (name, path) in discover() {
            if let Ok(t) = load(&path) {
                themes.push((name, t));
            }
        }
        for (name, t) in &themes {
            let cols: Vec<Rgba> = (0..6).map(|i| t.series(i)).collect();
            for (i, c) in cols.iter().enumerate() {
                // Against the CANVAS, which is the base.
                let on_base = Theme::contrast(*c, t.base());
                assert!(on_base >= 1.3, "{name}: series {i} is {on_base:.2} against the base");
            }
            // Neighbours differ: two adjacent slices of a pie in the same
            // colour is one slice.
            for i in 0..5 {
                let d = Theme::contrast(cols[i], cols[i + 1]);
                let same = (cols[i].r - cols[i + 1].r).abs() < 0.02
                    && (cols[i].g - cols[i + 1].g).abs() < 0.02
                    && (cols[i].b - cols[i + 1].b).abs() < 0.02;
                assert!(!same, "{name}: series {i} and {} are one colour ({d:.2})", i + 1);
            }
        }
        // And past the end they repeat rather than running out.
        let t = Theme::builtin();
        let n = (0..24).map(|i| t.series(i)).collect::<Vec<_>>();
        assert_eq!(n[0].r, n[6].r, "the seventh is the first again");
        // Every theme gives at least four distinguishable series: a pie of
        // four is the common case, and fewer would mean repeating inside one
        // chart.
        for (name, t) in &themes {
            let got: Vec<Rgba> = (0..6).map(|i| t.series(i)).collect();
            let mut uniq = 0;
            for i in 0..got.len() {
                if !got[..i].iter().any(|o| {
                    (o.r - got[i].r).abs() < 0.02
                        && (o.g - got[i].g).abs() < 0.02
                        && (o.b - got[i].b).abs() < 0.02
                }) {
                    uniq += 1;
                }
            }
            assert!(uniq >= 4, "{name}: only {uniq} distinguishable series");
        }
    }

    /// The DERIVED roles carry their own thresholds, on every theme installed.
    ///
    /// Not the editor's pairs — those are deliberately left at whatever
    /// contrast the editor has, which is the whole point of this file and is
    /// asserted below. These are the roles the editor does not define, where
    /// this client is the one making the choice and so has to be answerable
    /// for it: a selected row that cannot be seen is not a style, it is a grid
    /// that does not say where you are.
    ///
    /// Reads `$LODE_THEME_DIR` or the standard folders. With no theme files
    /// installed it still checks the built-in one, so it is never a test that
    /// passes by finding nothing.
    #[test]
    fn the_derived_roles_can_be_seen_on_every_theme() {
        let mut themes: Vec<(String, Theme)> = vec![("builtin".into(), Theme::builtin())];
        for (name, path) in discover() {
            if let Ok(t) = load(&path) {
                themes.push((name, t));
            }
        }
        let mut bad = Vec::new();
        for (name, t) in &themes {
            let checks = [
                ("selected_mark/panel", Theme::contrast(t.selected_mark(), t.panel()), 1.45),
                ("hover_mark/panel", Theme::contrast(t.hover_mark(), t.panel()), 1.18),
                ("disabled/panel", Theme::contrast(t.disabled(), t.panel()), 2.0),
                ("row_number/base", Theme::contrast(t.row_number(), t.base()), 2.0),
                ("divider/base", Theme::contrast(t.divider(), t.base()), 1.9),
            ];
            for (what, got, want) in checks {
                if got < want {
                    bad.push(format!("{name}: {what} is {got:.2}, wanted {want}"));
                }
            }
            // And a selection still has to be stronger than a hover, or the
            // row under the pointer and the row you are on look the same.
            if Theme::contrast(t.selected_mark(), t.panel())
                <= Theme::contrast(t.hover_mark(), t.panel())
            {
                bad.push(format!("{name}: a hover is louder than a selection"));
            }
        }
        assert!(
            bad.is_empty(),
            "{} of {} themes fail a DERIVED role:\n{}",
            bad.len(),
            themes.len(),
            bad.join("\n")
        );
    }

    /// `mix` stays between its two colours and reaches each of them.
    #[test]
    fn a_mix_introduces_no_colour_of_its_own() {
        let a = rgb(0x000000);
        let b = rgb(0xffffff);
        assert_eq!(Theme::mix(a, b, 0.0).r, b.r, "alpha 0 is the backdrop");
        assert_eq!(Theme::mix(a, b, 1.0).r, a.r, "alpha 1 is the overlay");
        let half = Theme::mix(a, b, 0.5);
        assert!(half.r > 0.49 && half.r < 0.51, "{}", half.r);
        // Out of range is clamped rather than wrapped.
        assert_eq!(Theme::mix(a, b, 2.0).r, a.r);
        assert_eq!(Theme::mix(a, b, -1.0).r, b.r);
        // Contrast is symmetric and at least 1.
        assert!((Theme::contrast(a, b) - Theme::contrast(b, a)).abs() < 0.001);
        assert!(Theme::contrast(a, a) >= 0.999 && Theme::contrast(a, a) <= 1.001);
        assert!(Theme::contrast(a, b) > 20.0, "black on white is the maximum");
    }

    /// The port must not have changed a single value: this is the editor's
    /// `Normal`, `Comment`, `StatusLine`, `CursorLine`, `PmenuSel` and `Visual`.
    #[test]
    fn the_builtin_theme_is_still_the_editors_base_dark() {
        let t = Theme::builtin();
        assert_eq!(t.surface.base, "#20272b", "Normal.bg");
        assert_eq!(t.text.primary, "#5e8888", "Normal.fg — NOT lifted for contrast");
        assert_eq!(t.text.muted, "#5b7d7e", "Comment.fg");
        assert_eq!(t.surface.status, "#1e2529", "StatusLine.bg");
        assert_eq!(t.surface.hover, "#2a373d", "CursorLine.bg");
        assert_eq!(t.surface.selected, "#243037", "PmenuSel.bg");
        assert_eq!(t.grid.selection_bg, "#22292d", "Visual.bg");
        assert_eq!(t.grid.selection_fg, t.text.primary, "Visual sets no fg");
        assert_eq!(t.grid.line_nr, "#2a373d", "LineNr.fg");
        // `surface.border` is the one deliberate departure from a literal
        // source group: `WinSeparator` equals its own background on all 48
        // styles (the editor draws no line between windows), and this client
        // puts a tree, a result, a console and a task list in ONE frame, where
        // no outline at all reads as one surface. It takes `LineNr` — the
        // quietest ink the editor really paints.
        assert_eq!(t.surface.border, "#2a373d", "LineNr.fg, used as the border");
    }

    /// The embedded copy must BE the generated file.
    ///
    /// It is a copy, not a symlink, because a crate has to build without the
    /// colorscheme checkout beside it. A copy can go stale, and it did: the
    /// generator moved `surface.border` from `WinSeparator` to `LineNr` and the
    /// embedded theme kept the old `#1e2529` for five days. This test is the
    /// thing that would have said so — it compares byte for byte when the
    /// checkout is there, and skips when it is not.
    #[test]
    fn the_embedded_theme_is_byte_for_byte_the_generated_one() {
        let Some(dir) = std::env::var_os("LODE_THEME_DIR") else {
            eprintln!("skipped: set LODE_THEME_DIR to compare against the generated themes");
            return;
        };
        let generated = std::path::PathBuf::from(dir).join("LvimBase_dark.toml");
        let Ok(text) = std::fs::read_to_string(&generated) else {
            eprintln!("skipped: no {} to compare against", generated.display());
            return;
        };
        assert_eq!(
            text,
            include_str!("builtin_theme.toml"),
            "crates/lode-ui/src/builtin_theme.toml is stale — copy {} over it",
            generated.display()
        );
    }

    /// The last two colours in the working code came from a literal; now they
    /// come from the built-in theme. The test says exactly that, so putting a
    /// number back would fail here rather than be noticed by eye.
    #[test]
    fn the_root_fallbacks_come_from_the_builtin_theme() {
        let b = Theme::builtin();
        assert_eq!(root_bg(), parse_hex(&b.surface.base).unwrap());
        assert_eq!(root_fg(), parse_hex(&b.text.primary).unwrap());
        // And a theme whose two roots are MISSING falls back to exactly those,
        // rather than to white on black. Built by blanking the built-in theme
        // rather than by hand-writing a skeleton: a skeleton drifts the moment a
        // role is added, and then this test fails for the wrong reason.
        let mut empty = Theme::builtin();
        empty.surface.base = String::new();
        empty.text.primary = String::new();
        assert_eq!(empty.base(), parse_hex(&b.surface.base).unwrap());
        assert_eq!(empty.fg(), parse_hex(&b.text.primary).unwrap());
    }

    /// Every real generated theme must load through the ported reader too.
    /// Pointed at the generator's output with `LODE_THEME_DIR`.
    #[test]
    fn every_generated_theme_loads() {
        let Some(dir) = std::env::var_os("LODE_THEME_DIR") else {
            eprintln!("skipped: set LODE_THEME_DIR to check the real themes");
            return;
        };
        let found = discover();
        assert!(!found.is_empty(), "no .toml themes in {dir:?}");
        for (name, path) in &found {
            let t = load(path).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(&t.name, name);
            assert_eq!(t.dark, !t.style.ends_with("_light"));
            assert_eq!(t.grid.selection_fg, t.text.primary);
            // A sentinel must never survive: an unparsed colour would be a
            // silent magenta in the window.
            for (what, v) in [
                ("surface.base", &t.surface.base),
                ("surface.status", &t.surface.status),
                ("surface.selected", &t.surface.selected),
                ("text.primary", &t.text.primary),
                ("text.title", &t.text.title),
                ("grid.line_nr", &t.grid.line_nr),
            ] {
                assert_ne!(hex(v, rgb(0x010203)).r, rgb(0x010203).r, "{name}: {what} = {v:?}");
            }
        }
        eprintln!("checked {} generated theme(s)", found.len());
    }

    #[test]
    fn a_badge_colour_is_never_nothing() {
        let t = Theme::builtin();
        for k in ["string", "int", "num", "bool", "null", "object", "array", "oid", "date", "whatever"] {
            let c = t.badge(k);
            assert!(c.a > 0.0, "{k} must have a visible colour");
        }
    }
}
